insert into kafaa_aps_scenarios (id, code, theme, title_en, title_ar, summary_en, summary_ar, context_en, context_ar, core_skill_ids, skill_ids, difficulty, est_minutes, stages, sources, status, version, sort, updated_by, updated_at) values
('aps-os-001', 'APS-OS-001', 'outage_schedule', 'The crane that arrives late', 'الرافعة التي تتأخر', 'A 12-hour maintenance window on a non-safety cooling-water pump: the crane slips, then a part does not fit.', 'نافذة صيانة مدتها 12 ساعة لمضخة مياه تبريد غير مرتبطة بالسلامة: تتأخر الرافعة ثم لا تناسب قطعة غيار.', 'You coordinate a planned 12-hour window (06:00-18:00) to replace the motor of a non-safety cooling-water pump. The plan: mobile crane at 07:00, motor lift at 08:00, coupling and guard fitted by 14:00, post-maintenance test at 16:00. The situation is synthetic.', 'تنسّق نافذة مخططة مدتها 12 ساعة (06:00-18:00) لاستبدال محرك مضخة مياه تبريد غير مرتبطة بالسلامة. الخطة: رافعة متنقلة الساعة 07:00، رفع المحرك الساعة 08:00، تركيب الوصلة والواقي بحلول 14:00، واختبار ما بعد الصيانة الساعة 16:00. الموقف افتراضي.', array['cs-adaptability','cs-problem']::text[], array['sk-fs-tr-resilience','sk-fs-tr-analytical']::text[], 2, 12, '[{"id":"plan","kind":"initial","info_en":"It is the day before the window. The crane is booked, the lifting plan is still waiting for approval, and the crew has not been briefed on what happens if the crane is late.","info_ar":"إنه اليوم السابق للنافذة. الرافعة محجوزة، وخطة الرفع ما زالت بانتظار الاعتماد، ولم يُطلَع الطاقم على ما يحدث إذا تأخرت الرافعة.","question_en":"What do you do first?","question_ar":"ما أول ما تفعله؟","options":[{"en":"Get the lifting plan approved today, reconfirm the crane, and brief the crew on a hold point and fallback tasks if the crane is late.","ar":"أعتمد خطة الرفع اليوم، وأعيد تأكيد الرافعة، وأُطلع الطاقم على نقطة توقف ومهام بديلة إذا تأخرت الرافعة.","eff":3,"note_en":"Removes the known risks before the window opens and gives the crew a plan B.","note_ar":"يزيل المخاطر المعروفة قبل فتح النافذة ويمنح الطاقم خطة بديلة."},{"en":"Start dismantling at 05:00 tomorrow to gain time, even before the lifting plan is approved.","ar":"أبدأ التفكيك الساعة 05:00 غداً لكسب الوقت حتى قبل اعتماد خطة الرفع.","eff":0,"note_en":"Starts work outside the approved plan and window: speed is not worth an uncontrolled start.","note_ar":"يبدأ العمل خارج الخطة والنافذة المعتمدتين: السرعة لا تبرر بداية غير منضبطة."},{"en":"Ask the insulation contractor to come early so the crew is never idle.","ar":"أطلب من مقاول العزل الحضور مبكراً حتى لا يبقى الطاقم دون عمل.","eff":1,"note_en":"Fills time but leaves the lifting plan and the crane risk open.","note_ar":"يملأ الوقت لكنه يترك خطة الرفع ومخاطر الرافعة دون معالجة."},{"en":"Keep the plan as written and deal with problems as they come.","ar":"أُبقي الخطة كما هي وأتعامل مع المشكلات عند ظهورها.","eff":1,"note_en":"A plan with no fallback turns every slip into an improvised decision.","note_ar":"الخطة بلا بديل تحوّل كل تأخير إلى قرار مرتجل."}],"cues":[{"en":"The lifting plan is still waiting for approval.","ar":"خطة الرفع ما زالت بانتظار الاعتماد.","relevant":true},{"en":"The crane is booked for 07:00.","ar":"الرافعة محجوزة للساعة 07:00.","relevant":true},{"en":"The canteen opens at 06:30.","ar":"يفتح المقصف الساعة 06:30.","relevant":false},{"en":"The car park will be resurfaced next week.","ar":"سيُعاد رصف موقف السيارات الأسبوع القادم.","relevant":false}],"debrief_en":"Adaptive problem solving starts before anything changes: name the weak points of the plan (an unapproved lift, a single crane) and agree what the crew does if they fail.","debrief_ar":"يبدأ حل المشكلات التكيّفي قبل أن يتغير شيء: حدّد نقاط ضعف الخطة (رفع غير معتمد ورافعة واحدة) واتفق مع الطاقم على ما يفعله إذا تعثرت."},{"id":"crane","kind":"change","info_en":"06:40. The crane operator calls: the crane is held at another job and will arrive at 11:00, four hours late. The isolation checks and the scaffolding do not need the crane. The test team can stay until 19:00.","info_ar":"06:40. يتصل مشغل الرافعة: الرافعة محتجزة في عمل آخر وستصل الساعة 11:00، أي بتأخير أربع ساعات. فحوص العزل والسقالات لا تحتاج إلى الرافعة. ويمكن لفريق الاختبار البقاء حتى 19:00.","question_en":"What do you do now?","question_ar":"ماذا تفعل الآن؟","options":[{"en":"Keep the original sequence and wait for the crane.","ar":"أُبقي التسلسل الأصلي وأنتظر الرافعة.","eff":1,"note_en":"Four idle hours push every later step past the window.","note_ar":"أربع ساعات من الانتظار تدفع كل الخطوات اللاحقة إلى ما بعد النافذة.","keep":true},{"en":"Re-sequence: do the isolation checks and scaffolding now, move the lift to 11:00, and tell the planner and the test team the new times.","ar":"أعيد الترتيب: أنفذ فحوص العزل والسقالات الآن، وأنقل الرفع إلى 11:00، وأُبلغ المخطط وفريق الاختبار بالمواعيد الجديدة.","eff":3,"note_en":"Uses the facts that changed and the ones that did not; everyone affected hears the new plan.","note_ar":"يستفيد مما تغيّر ومما لم يتغيّر، ويعرف كل المعنيين الخطة الجديدة."},{"en":"Lift the motor with a forklift instead.","ar":"أرفع المحرك برافعة شوكية بدلاً من ذلك.","eff":0,"note_en":"An unplanned lifting method is a new hazard, not a fix.","note_ar":"طريقة رفع غير مخططة خطر جديد وليست حلاً."},{"en":"Cancel the job and give the window back.","ar":"ألغي العمل وأعيد النافذة.","eff":1,"note_en":"Too early: the window can still close safely with a new sequence.","note_ar":"مبكر جداً: ما زال يمكن إغلاق النافذة بأمان بتسلسل جديد."}],"cues":[{"en":"The crane now arrives at 11:00.","ar":"الرافعة ستصل الآن الساعة 11:00.","relevant":true},{"en":"Isolation checks and scaffolding do not need the crane.","ar":"فحوص العزل والسقالات لا تحتاج إلى الرافعة.","relevant":true},{"en":"The test team can stay until 19:00.","ar":"يمكن لفريق الاختبار البقاء حتى 19:00.","relevant":true},{"en":"The crane operator is new to the company.","ar":"مشغل الرافعة جديد في الشركة.","relevant":false}],"debrief_en":"The change matters, so the plan changes: move the independent tasks forward and tell everyone whose time moves. Waiting is a decision too, and here it costs the window.","debrief_ar":"التغيير مهم، لذلك تتغير الخطة: قدّم المهام المستقلة وأبلغ كل من يتغير توقيته. الانتظار قرار أيضاً، وهنا يكلّف النافذة."},{"id":"guard","kind":"change","info_en":"13:30. The motor is in place, but the new coupling guard is the wrong size. A correct guard can be made by 17:30. The window ends at 18:00; the test needs one hour.","info_ar":"13:30. المحرك في مكانه، لكن واقي الوصلة الجديد بمقاس خاطئ. يمكن تصنيع واقٍ صحيح بحلول 17:30. تنتهي النافذة الساعة 18:00 ويحتاج الاختبار إلى ساعة.","question_en":"What do you do now?","question_ar":"ماذا تفعل الآن؟","options":[{"en":"Run the test at 16:00 without the guard.","ar":"أجري الاختبار الساعة 16:00 دون الواقي.","eff":0,"note_en":"Testing rotating equipment without its guard trades safety for the schedule.","note_ar":"اختبار معدات دوّارة دون واقيها يقايض السلامة بالجدول."},{"en":"Fit the old guard quietly so the test can run on time.","ar":"أركّب الواقي القديم دون إبلاغ أحد ليجري الاختبار في موعده.","eff":0,"note_en":"An undocumented change hides a configuration question from the people who own it.","note_ar":"تغيير غير موثّق يخفي مسألة تهيئة عن أصحاب القرار فيها."},{"en":"Bring the facts to the outage manager now: guard ready 17:30, test needs an hour, window ends 18:00; propose a one-hour extension or a test early tomorrow.","ar":"أعرض الحقائق على مدير الصيانة الدورية الآن: الواقي جاهز 17:30، والاختبار يحتاج ساعة، والنافذة تنتهي 18:00؛ وأقترح تمديداً لساعة أو اختباراً صباح الغد.","eff":3,"note_en":"The numbers no longer fit the window, so the decision goes to its owner early, with options.","note_ar":"الأرقام لم تعد تتسع في النافذة، فيذهب القرار إلى صاحبه مبكراً ومعه خيارات."},{"en":"Keep the 16:00 test in the plan and hope the workshop is faster.","ar":"أُبقي اختبار 16:00 في الخطة وآمل أن تُنجز الورشة العمل أسرع.","eff":1,"note_en":"Hope is not a plan: the window problem stays hidden until 17:30.","note_ar":"الأمل ليس خطة: مشكلة النافذة تبقى مخفية حتى 17:30.","keep":true}],"cues":[{"en":"The correct guard is ready at 17:30.","ar":"الواقي الصحيح جاهز الساعة 17:30.","relevant":true},{"en":"The test needs one hour and the window ends at 18:00.","ar":"يحتاج الاختبار إلى ساعة وتنتهي النافذة الساعة 18:00.","relevant":true},{"en":"The new motor is painted a different colour.","ar":"المحرك الجديد مطلي بلون مختلف.","relevant":false},{"en":"The morning briefing ran ten minutes long.","ar":"استغرقت إحاطة الصباح عشر دقائق إضافية.","relevant":false}],"debrief_en":"When the facts no longer fit the plan, say so early and bring options. The worst answers keep the schedule by quietly dropping a safety feature.","debrief_ar":"عندما لا تعود الحقائق متسقة مع الخطة، قل ذلك مبكراً واطرح خيارات. أسوأ الإجابات تحافظ على الجدول بالتخلي بصمت عن وسيلة أمان."}]'::jsonb, '[{"label":"OECD Survey of Adult Skills (PIAAC), Cycle 2 database: adaptive problem solving","url":"https://www.oecd.org/en/data/datasets/PIAAC-2nd-Cycle-Database.html","as_of":"2026-10-10","benchmark_id":"OECD-PIAAC"},{"label":"CSO Ireland · PIAAC 2023 key findings (publishes the OECD averages)","url":"https://www.cso.ie/en/releasesandpublications/ep/p-piaac/programmefortheinternationalassessmentofadultcompetenciespiaac2023/keyfindings","as_of":"2026-10-10","benchmark_id":"OECD-PIAAC"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10","benchmark_id":"IAEA-1917"}]'::jsonb, 'published', 1, 1, 'p-training-mgr', '2026-09-28T09:00:00Z'),
('aps-cd-001', 'APS-CD-001', 'conflicting_data', 'Two readings that disagree', 'قراءتان متعارضتان', 'A sample result and an online analyser disagree; then a recalibration record turns up.', 'نتيجة عينة ومحلل آلي يختلفان، ثم يظهر سجل معايرة.', 'You prepare the morning summary of water-chemistry trends for a non-safety auxiliary system. The online analyser and the laboratory sample normally agree within 5%. The situation is synthetic.', 'تُعدّ ملخص الصباح لاتجاهات كيمياء المياه لنظام مساعد غير مرتبط بالسلامة. يتفق المحلل الآلي وعينة المختبر عادة ضمن 5%. الموقف افتراضي.', array['cs-questioning','cs-problem']::text[], array['sk-fs-tr-analytical','sk-fs-ai-plantdata']::text[], 2, 10, '[{"id":"plan","kind":"initial","info_en":"This morning the online analyser reads 40% higher than yesterday, but the laboratory sample taken at the same time is unchanged. The summary goes to the shift at 09:00.","info_ar":"هذا الصباح يقرأ المحلل الآلي أعلى بنسبة 40% من الأمس، لكن عينة المختبر المأخوذة في الوقت نفسه لم تتغير. يُرسل الملخص إلى النوبة الساعة 09:00.","question_en":"What do you do first?","question_ar":"ما أول ما تفعله؟","options":[{"en":"Report the analyser value as the trend; it is the official online instrument.","ar":"أبلغ عن قيمة المحلل بوصفها الاتجاه؛ فهو الجهاز الآلي الرسمي.","eff":0,"note_en":"Picks one source without explaining a disagreement eight times wider than normal.","note_ar":"يختار مصدراً واحداً دون تفسير خلاف أوسع بثماني مرات من المعتاد."},{"en":"Show both values in the summary, flag the disagreement as unresolved, and ask for a check of the analyser and a repeat sample.","ar":"أعرض القيمتين في الملخص، وأشير إلى الخلاف بوصفه غير محسوم، وأطلب فحص المحلل وأخذ عينة مكررة.","eff":3,"note_en":"Keeps the uncertainty visible and starts the checks that will resolve it.","note_ar":"يُبقي عدم اليقين ظاهراً ويبدأ الفحوص التي ستحسمه."},{"en":"Average the two values and report the average.","ar":"أحسب متوسط القيمتين وأبلغ عنه.","eff":0,"note_en":"An average of two disagreeing readings is a number nobody measured.","note_ar":"متوسط قراءتين متعارضتين رقم لم يقِسه أحد."},{"en":"Leave the parameter out of the summary until it is sorted.","ar":"أحذف المؤشر من الملخص حتى يُحسم.","eff":1,"note_en":"Hides a question the shift should know about.","note_ar":"يخفي سؤالاً ينبغي أن تعرفه النوبة."}],"cues":[{"en":"The two sources normally agree within 5%.","ar":"يتفق المصدران عادة ضمن 5%.","relevant":true},{"en":"The analyser jumped 40% while the sample did not move.","ar":"قفز المحلل 40% بينما لم تتحرك العينة.","relevant":true},{"en":"The summary template changed font last month.","ar":"تغيّر خط قالب الملخص الشهر الماضي.","relevant":false},{"en":"The laboratory is in a different building.","ar":"المختبر في مبنى مختلف.","relevant":false}],"debrief_en":"When sources disagree far beyond their normal spread, report the disagreement itself and start the checks. Averaging or picking a favourite hides the problem.","debrief_ar":"عندما يختلف مصدران بأكثر بكثير من تباينهما المعتاد، أبلغ عن الخلاف نفسه وابدأ الفحوص. حساب المتوسط أو تفضيل مصدر يخفي المشكلة."},{"id":"calib","kind":"change","info_en":"08:20. Instrument maintenance tells you the analyser was recalibrated at 06:00 with a new reagent batch. The repeat laboratory sample at 08:00 matches the first sample.","info_ar":"08:20. تخبرك صيانة الأجهزة بأن المحلل أُعيدت معايرته الساعة 06:00 بدفعة كاشف جديدة. وعينة المختبر المكررة الساعة 08:00 تطابق العينة الأولى.","question_en":"What do you do now?","question_ar":"ماذا تفعل الآن؟","options":[{"en":"Treat the laboratory value as the best estimate, mark the analyser suspect since the 06:00 recalibration, and ask instrument maintenance to verify the reagent batch.","ar":"أعدّ قيمة المختبر أفضل تقدير، وأصنّف المحلل مشكوكاً فيه منذ معايرة 06:00، وأطلب من صيانة الأجهزة التحقق من دفعة الكاشف.","eff":3,"note_en":"The new facts point to the instrument change; the summary says so and the check is assigned.","note_ar":"الحقائق الجديدة تشير إلى تغيير الجهاز؛ ويذكر الملخص ذلك ويُكلَّف أحد بالفحص."},{"en":"Keep the summary as you drafted it: both values, unresolved.","ar":"أُبقي الملخص كما كتبته: القيمتان، دون حسم.","eff":1,"note_en":"You now know more; leaving it \"unresolved\" wastes the new evidence.","note_ar":"أنت تعرف الآن أكثر؛ وترك المسألة \"دون حسم\" يهدر الدليل الجديد.","keep":true},{"en":"Report the analyser value again: it was just calibrated, so it must be right.","ar":"أعيد الإبلاغ عن قيمة المحلل: لقد عوير للتو فلا بد أنه صحيح.","eff":0,"note_en":"A fresh calibration is exactly when a reagent or setup error appears.","note_ar":"المعايرة الحديثة هي بالضبط الوقت الذي يظهر فيه خطأ كاشف أو إعداد."},{"en":"Close the question: the laboratory is always right.","ar":"أغلق المسألة: المختبر دائماً على حق.","eff":1,"note_en":"Right answer for today, wrong rule: the analyser still needs its check.","note_ar":"إجابة صحيحة اليوم وقاعدة خاطئة: المحلل ما زال بحاجة إلى فحصه."}],"cues":[{"en":"The analyser was recalibrated at 06:00 with a new reagent batch.","ar":"أُعيدت معايرة المحلل الساعة 06:00 بدفعة كاشف جديدة.","relevant":true},{"en":"The repeat sample matches the first sample.","ar":"العينة المكررة تطابق العينة الأولى.","relevant":true},{"en":"Instrument maintenance moved to a new office.","ar":"انتقلت صيانة الأجهزة إلى مكتب جديد.","relevant":false},{"en":"Yesterday''s summary was sent at 09:05.","ar":"أُرسل ملخص الأمس الساعة 09:05.","relevant":false}],"debrief_en":"New information should move your conclusion. A recalibration just before the jump and a repeat sample that agrees with the first both point to the instrument.","debrief_ar":"ينبغي أن تُغيّر المعلومات الجديدة استنتاجك. معايرة قبل القفزة مباشرة وعينة مكررة تطابق الأولى تشيران كلتاهما إلى الجهاز."},{"id":"font","kind":"change","info_en":"08:50. The shift supervisor asks you to use the new summary template from today; it only changes the layout, not the content.","info_ar":"08:50. يطلب منك مشرف النوبة استخدام قالب الملخص الجديد بدءاً من اليوم؛ وهو يغيّر الشكل فقط لا المحتوى.","question_en":"What do you do now?","question_ar":"ماذا تفعل الآن؟","options":[{"en":"Rewrite your conclusions to fit the new template''s headings.","ar":"أعيد صياغة استنتاجاتي لتناسب عناوين القالب الجديد.","eff":1,"note_en":"The layout changed, not the facts; rewriting risks losing the key point.","note_ar":"تغيّر الشكل لا الحقائق؛ وإعادة الصياغة قد تُضيع النقطة الأساسية."},{"en":"Move the same content into the new template and send it at 09:00, with the analyser flag at the top.","ar":"أنقل المحتوى نفسه إلى القالب الجديد وأرسله الساعة 09:00 مع إشارة المحلل في الأعلى.","eff":3,"note_en":"Not every change needs a new plan: this one changes the format only.","note_ar":"ليس كل تغيير يحتاج خطة جديدة: هذا التغيير يمس الشكل فقط.","keep":true},{"en":"Delay the summary until you have learned the new template.","ar":"أؤخر الملخص حتى أتعلم القالب الجديد.","eff":0,"note_en":"The shift loses the analyser warning for a layout change.","note_ar":"تخسر النوبة تحذير المحلل بسبب تغيير في الشكل."},{"en":"Send the old template today and switch tomorrow, telling the supervisor why.","ar":"أرسل القالب القديم اليوم وأنتقل غداً، وأشرح السبب للمشرف.","eff":2,"note_en":"Reasonable, but the switch was cheap and the request was for today.","note_ar":"معقول، لكن الانتقال كان سهلاً والطلب كان لليوم."}],"cues":[{"en":"The new template changes layout only.","ar":"القالب الجديد يغيّر الشكل فقط.","relevant":true},{"en":"The summary is due at 09:00.","ar":"موعد الملخص الساعة 09:00.","relevant":true},{"en":"The template was designed by another department.","ar":"صمّم القالب قسم آخر.","relevant":false},{"en":"The supervisor prefers a larger font.","ar":"يفضّل المشرف خطاً أكبر.","relevant":false}],"debrief_en":"This change does not affect the problem, so the plan stays: same content, new layout, on time. Over-reacting to a minor change is a common adaptive-problem-solving error.","debrief_ar":"هذا التغيير لا يمس المشكلة، لذلك تبقى الخطة: المحتوى نفسه بشكل جديد وفي الموعد. المبالغة في الاستجابة لتغيير بسيط خطأ شائع في حل المشكلات التكيّفي."}]'::jsonb, '[{"label":"OECD Survey of Adult Skills (PIAAC), Cycle 2 database: adaptive problem solving","url":"https://www.oecd.org/en/data/datasets/PIAAC-2nd-Cycle-Database.html","as_of":"2026-10-10","benchmark_id":"OECD-PIAAC"},{"label":"CSO Ireland · PIAAC 2023 key findings (publishes the OECD averages)","url":"https://www.cso.ie/en/releasesandpublications/ep/p-piaac/programmefortheinternationalassessmentofadultcompetenciespiaac2023/keyfindings","as_of":"2026-10-10","benchmark_id":"OECD-PIAAC"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10","benchmark_id":"IAEA-1917"}]'::jsonb, 'published', 1, 2, 'p-training-mgr', '2026-09-28T09:00:00Z'),
('aps-sd-001', 'APS-SD-001', 'supply_delay', 'The spare part that is stuck in customs', 'قطعة الغيار العالقة في الجمارك', 'A planned bearing replacement depends on a part that is delayed, then an alternative supplier appears.', 'استبدال محمل مخطط يعتمد على قطعة متأخرة، ثم يظهر مورد بديل.', 'You plan the replacement of a worn bearing on a ventilation fan in an office building on site (non-safety). The fan still runs but its vibration trend is rising slowly. The part was due on Monday. The situation is synthetic.', 'تخطط لاستبدال محمل متآكل في مروحة تهوية بمبنى مكاتب في الموقع (غير مرتبط بالسلامة). ما زالت المروحة تعمل لكن اتجاه اهتزازها يرتفع ببطء. كان موعد وصول القطعة يوم الاثنين. الموقف افتراضي.', array['cs-adaptability','cs-systems']::text[], array['sk-fs-tr-systems','sk-fs-tr-resilience']::text[], 1, 8, '[{"id":"plan","kind":"initial","info_en":"The work is booked for Tuesday. The bearing is ordered from the usual supplier; nobody has checked its delivery status this week.","info_ar":"العمل محجوز ليوم الثلاثاء. المحمل مطلوب من المورد المعتاد، ولم يتحقق أحد من حالة التسليم هذا الأسبوع.","question_en":"What do you do first?","question_ar":"ما أول ما تفعله؟","options":[{"en":"Check the delivery status now and agree a vibration limit at which the fan is stopped if the part is late.","ar":"أتحقق من حالة التسليم الآن وأتفق على حد اهتزاز تُوقف المروحة عنده إذا تأخرت القطعة.","eff":3,"note_en":"Confirms the dependency and sets a safe trigger in advance.","note_ar":"يؤكد الاعتماد على القطعة ويضع مسبقاً معياراً آمناً للتصرف."},{"en":"Assume the part arrives Monday as usual.","ar":"أفترض أن القطعة ستصل يوم الاثنين كالمعتاد.","eff":1,"note_en":"The plan rests on a fact nobody checked.","note_ar":"تقوم الخطة على حقيقة لم يتحقق منها أحد."},{"en":"Stop the fan today to protect it.","ar":"أوقف المروحة اليوم لحمايتها.","eff":1,"note_en":"Premature: the trend is rising slowly and the building needs ventilation.","note_ar":"سابق لأوانه: الاتجاه يرتفع ببطء والمبنى يحتاج إلى التهوية."},{"en":"Order a second bearing from another supplier just in case.","ar":"أطلب محملاً ثانياً من مورد آخر احتياطاً.","eff":2,"note_en":"Hedges the risk but skips checking the first order.","note_ar":"يتحوّط من المخاطرة لكنه يتجاوز التحقق من الطلب الأول."}],"cues":[{"en":"Nobody has checked the delivery status this week.","ar":"لم يتحقق أحد من حالة التسليم هذا الأسبوع.","relevant":true},{"en":"The vibration trend is rising slowly.","ar":"اتجاه الاهتزاز يرتفع ببطء.","relevant":true},{"en":"The fan was painted last year.","ar":"طُليت المروحة العام الماضي.","relevant":false},{"en":"The office building has two entrances.","ar":"لمبنى المكاتب مدخلان.","relevant":false}],"debrief_en":"Check the facts the plan depends on and agree in advance what would make you change it (here, a vibration limit).","debrief_ar":"تحقق من الحقائق التي تعتمد عليها الخطة واتفق مسبقاً على ما يجعلك تغيّرها (هنا حد للاهتزاز)."},{"id":"customs","kind":"change","info_en":"Monday. The supplier says the bearing is held in customs for at least ten days. An approved alternative supplier can deliver an equivalent bearing on Wednesday. The vibration is still below the agreed limit.","info_ar":"الاثنين. يقول المورد إن المحمل محتجز في الجمارك عشرة أيام على الأقل. ويستطيع مورد بديل معتمد تسليم محمل مكافئ يوم الأربعاء. وما زال الاهتزاز دون الحد المتفق عليه.","question_en":"What do you do now?","question_ar":"ماذا تفعل الآن؟","options":[{"en":"Wait for the original part.","ar":"أنتظر القطعة الأصلية.","eff":1,"note_en":"Ten more days of a rising trend, when an approved option exists.","note_ar":"عشرة أيام أخرى من اتجاه متصاعد مع وجود خيار معتمد.","keep":true},{"en":"Order from the approved alternative, move the job to Thursday, keep monitoring against the limit, and tell the building owner.","ar":"أطلب من المورد البديل المعتمد، وأنقل العمل إلى الخميس، وأواصل المراقبة مقارنة بالحد، وأُبلغ مالك المبنى.","eff":3,"note_en":"Re-plans around the new fact with an approved source and keeps the safety trigger in place.","note_ar":"يعيد التخطيط حول الحقيقة الجديدة بمصدر معتمد ويُبقي معيار السلامة قائماً."},{"en":"Buy a bearing from a local shop that is not on the approved list.","ar":"أشتري محملاً من متجر محلي غير مدرج في القائمة المعتمدة.","eff":0,"note_en":"Speed by bypassing supplier approval creates a quality risk.","note_ar":"السرعة بتجاوز اعتماد الموردين تخلق خطراً على الجودة."},{"en":"Stop the fan now until any part arrives.","ar":"أوقف المروحة الآن حتى تصل أي قطعة.","eff":1,"note_en":"The vibration is below the limit; stopping now has a cost and no benefit yet.","note_ar":"الاهتزاز دون الحد؛ والإيقاف الآن له كلفة دون فائدة بعد."}],"cues":[{"en":"The original part is held for ten days or more.","ar":"القطعة الأصلية محتجزة عشرة أيام أو أكثر.","relevant":true},{"en":"An approved alternative can deliver on Wednesday.","ar":"يستطيع مورد بديل معتمد التسليم يوم الأربعاء.","relevant":true},{"en":"Vibration is still below the agreed limit.","ar":"الاهتزاز ما زال دون الحد المتفق عليه.","relevant":true},{"en":"The supplier''s sales contact changed.","ar":"تغيّر مسؤول المبيعات لدى المورد.","relevant":false}],"debrief_en":"The delay changes the plan; the safety trigger does not. Approved alternatives are part of adaptive planning; unapproved shortcuts are not.","debrief_ar":"التأخير يغيّر الخطة، أما معيار السلامة فلا يتغير. البدائل المعتمدة جزء من التخطيط التكيّفي، أما الطرق المختصرة غير المعتمدة فلا."}]'::jsonb, '[{"label":"OECD Survey of Adult Skills (PIAAC), Cycle 2 database: adaptive problem solving","url":"https://www.oecd.org/en/data/datasets/PIAAC-2nd-Cycle-Database.html","as_of":"2026-10-10","benchmark_id":"OECD-PIAAC"},{"label":"CSO Ireland · PIAAC 2023 key findings (publishes the OECD averages)","url":"https://www.cso.ie/en/releasesandpublications/ep/p-piaac/programmefortheinternationalassessmentofadultcompetenciespiaac2023/keyfindings","as_of":"2026-10-10","benchmark_id":"OECD-PIAAC"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10","benchmark_id":"IAEA-1917"}]'::jsonb, 'published', 1, 3, 'p-training-mgr', '2026-09-28T09:00:00Z'),
('aps-sc-001', 'APS-SC-001', 'staffing_change', 'Two people short on a training day', 'نقص شخصين في يوم تدريب', 'A classroom day for twelve trainees loses its second instructor, then the simulator slot moves.', 'يوم تدريب صفي لاثني عشر متدرباً يفقد مدربه الثاني، ثم يتغير موعد المحاكي.', 'You run a training day for twelve trainees: a classroom session in the morning with two instructors, and a practical session on a part-task trainer in the afternoon. The situation is synthetic.', 'تدير يوم تدريب لاثني عشر متدرباً: جلسة صفية صباحاً بمدربين اثنين، وجلسة عملية على جهاز تدريب جزئي بعد الظهر. الموقف افتراضي.', array['cs-adaptability','cs-conservative']::text[], array['sk-fs-tr-resilience','sk-fs-tr-leadership']::text[], 2, 10, '[{"id":"plan","kind":"initial","info_en":"The day is planned in two groups of six. The second instructor is confirmed. The part-task trainer is booked from 13:00 to 17:00.","info_ar":"اليوم مخطط على مجموعتين من ستة متدربين. المدرب الثاني مؤكد. جهاز التدريب الجزئي محجوز من 13:00 إلى 17:00.","question_en":"What do you do first?","question_ar":"ما أول ما تفعله؟","options":[{"en":"Confirm rooms and the trainer booking and prepare a one-instructor version of the afternoon in case someone drops out.","ar":"أؤكد القاعات وحجز الجهاز وأُعدّ نسخة من جلسة بعد الظهر لمدرب واحد تحسباً لغياب أحد.","eff":3,"note_en":"A cheap fallback for the most fragile part of the day.","note_ar":"بديل قليل الكلفة للجزء الأضعف من اليوم."},{"en":"Nothing extra: the plan is confirmed.","ar":"لا شيء إضافي: الخطة مؤكدة.","eff":1,"note_en":"Confirmed is not the same as robust.","note_ar":"المؤكد لا يعني المتين."},{"en":"Cut the practical session to save effort.","ar":"أختصر الجلسة العملية لتوفير الجهد.","eff":0,"note_en":"Removes the part of the day that builds the skill.","note_ar":"يحذف الجزء من اليوم الذي يبني المهارة."}],"cues":[{"en":"The afternoon needs two instructors for two groups.","ar":"تحتاج جلسة بعد الظهر إلى مدربين لمجموعتين.","relevant":true},{"en":"The part-task trainer is booked 13:00-17:00.","ar":"جهاز التدريب الجزئي محجوز 13:00-17:00.","relevant":true},{"en":"The trainees come from three departments.","ar":"يأتي المتدربون من ثلاثة أقسام.","relevant":false}],"debrief_en":"Robust plans have a cheap fallback for their most fragile part.","debrief_ar":"الخطط المتينة لديها بديل قليل الكلفة لأضعف أجزائها."},{"id":"sick","kind":"change","info_en":"07:30. The second instructor calls in sick. A qualified colleague can join at 13:00 but not in the morning.","info_ar":"07:30. يتصل المدرب الثاني معتذراً بسبب المرض. يمكن لزميل مؤهل الانضمام الساعة 13:00 لكن ليس صباحاً.","question_en":"What do you do now?","question_ar":"ماذا تفعل الآن؟","options":[{"en":"Run the morning classroom as one group of twelve with one instructor, and the afternoon practical in two groups with the colleague.","ar":"أدير الجلسة الصفية صباحاً مجموعةً واحدة من اثني عشر مع مدرب واحد، والجلسة العملية بعد الظهر بمجموعتين مع الزميل.","eff":3,"note_en":"Moves the shortage to where it hurts least: a classroom can take twelve, a practical cannot.","note_ar":"ينقل النقص إلى حيث يضر أقل: الصف يتسع لاثني عشر، أما الجلسة العملية فلا."},{"en":"Keep two groups in the morning; one group studies alone.","ar":"أُبقي مجموعتين صباحاً وتدرس إحداهما وحدها.","eff":1,"note_en":"Half the trainees get no instruction.","note_ar":"نصف المتدربين لا يحصلون على تدريب.","keep":true},{"en":"Cancel the whole day.","ar":"ألغي اليوم بأكمله.","eff":0,"note_en":"Throws away a day that can still run well.","note_ar":"يهدر يوماً ما زال يمكن أن ينجح."},{"en":"Ask a non-qualified colleague to supervise the practical.","ar":"أطلب من زميل غير مؤهل الإشراف على الجلسة العملية.","eff":0,"note_en":"Practical training needs a qualified instructor.","note_ar":"التدريب العملي يحتاج إلى مدرب مؤهل."}],"cues":[{"en":"A qualified colleague is free from 13:00.","ar":"زميل مؤهل متاح من الساعة 13:00.","relevant":true},{"en":"The morning is classroom only.","ar":"الصباح جلسة صفية فقط.","relevant":true},{"en":"The sick instructor usually teaches on Tuesdays.","ar":"يدرّس المدرب المريض عادة أيام الثلاثاء.","relevant":false}],"debrief_en":"Re-allocate the scarce resource to the activity that needs it most, and keep the qualification rule intact.","debrief_ar":"أعد توزيع المورد الشحيح على النشاط الأحوج إليه، وحافظ على قاعدة التأهيل."},{"id":"slot","kind":"change","info_en":"11:00. Engineering needs the part-task trainer from 15:00 for an urgent check. You keep it 13:00-15:00 only.","info_ar":"11:00. يحتاج قسم الهندسة إلى جهاز التدريب الجزئي من الساعة 15:00 لفحص عاجل. يبقى لك من 13:00 إلى 15:00 فقط.","question_en":"What do you do now?","question_ar":"ماذا تفعل الآن؟","options":[{"en":"Run both practical groups at 90 minutes each, back to back, on a shortened exercise, and book the missing practice for next week.","ar":"أدير المجموعتين العمليتين 90 دقيقة لكل منهما متتاليتين على تمرين مختصر، وأحجز التدريب الناقص للأسبوع القادم.","eff":2,"note_en":"Workable, but 2 x 90 minutes does not fit in two hours.","note_ar":"قابل للتنفيذ، لكن 2 × 90 دقيقة لا تتسع في ساعتين."},{"en":"Run both groups in parallel 13:00-15:00 with both instructors on the core exercise, and book the remaining exercise for next week.","ar":"أدير المجموعتين بالتوازي 13:00-15:00 مع المدربين على التمرين الأساسي، وأحجز التمرين المتبقي للأسبوع القادم.","eff":3,"note_en":"Fits the new two hours and protects the core exercise; the rest is rebooked.","note_ar":"يتسع في الساعتين الجديدتين ويحمي التمرين الأساسي؛ ويُعاد حجز الباقي."},{"en":"Refuse to give the trainer up.","ar":"أرفض التخلي عن الجهاز.","eff":0,"note_en":"An urgent engineering check outranks a training slot.","note_ar":"الفحص الهندسي العاجل يتقدم على موعد تدريب.","keep":true},{"en":"Skip the practical today.","ar":"ألغي الجلسة العملية اليوم.","eff":1,"note_en":"Two good hours are still available.","note_ar":"ما زالت هناك ساعتان مفيدتان."}],"cues":[{"en":"You now have the trainer 13:00-15:00.","ar":"أصبح الجهاز متاحاً لك 13:00-15:00.","relevant":true},{"en":"Both instructors are available in the afternoon.","ar":"المدربان متاحان بعد الظهر.","relevant":true},{"en":"Engineering requested the slot by e-mail.","ar":"طلب قسم الهندسة الموعد بالبريد الإلكتروني.","relevant":false},{"en":"The trainees had lunch at 12:00.","ar":"تناول المتدربون الغداء الساعة 12:00.","relevant":false}],"debrief_en":"Check that the new plan really fits the new constraint; then protect what matters most and rebook the rest.","debrief_ar":"تحقق من أن الخطة الجديدة تتسع فعلاً للقيد الجديد، ثم احمِ الأهم وأعد حجز الباقي."}]'::jsonb, '[{"label":"OECD Survey of Adult Skills (PIAAC), Cycle 2 database: adaptive problem solving","url":"https://www.oecd.org/en/data/datasets/PIAAC-2nd-Cycle-Database.html","as_of":"2026-10-10","benchmark_id":"OECD-PIAAC"},{"label":"CSO Ireland · PIAAC 2023 key findings (publishes the OECD averages)","url":"https://www.cso.ie/en/releasesandpublications/ep/p-piaac/programmefortheinternationalassessmentofadultcompetenciespiaac2023/keyfindings","as_of":"2026-10-10","benchmark_id":"OECD-PIAAC"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10","benchmark_id":"IAEA-1917"}]'::jsonb, 'published', 1, 4, 'p-training-mgr', '2026-09-28T09:00:00Z'),
('aps-pr-001', 'APS-PR-001', 'procedure_revision', 'A procedure revision issued mid-job', 'مراجعة إجراء تصدر أثناء العمل', 'A routine calibration task: a new revision of the procedure is issued halfway through, then the difference turns out to be small.', 'مهمة معايرة روتينية: تصدر مراجعة جديدة للإجراء في منتصف العمل، ثم يتبين أن الفرق صغير.', 'You lead a routine calibration of non-safety temperature transmitters in a workshop, following a controlled procedure (synthetic revision C). Steps 1-6 of 12 are done. The situation is synthetic.', 'تقود معايرة روتينية لمرسلات حرارة غير مرتبطة بالسلامة في ورشة، باتباع إجراء مضبوط (المراجعة الافتراضية C). أُنجزت الخطوات 1-6 من 12. الموقف افتراضي.', array['cs-procedure','cs-adaptability','cs-conservative']::text[], array['sk-fs-tr-dependable','sk-fs-tr-analytical']::text[], 3, 14, '[{"id":"plan","kind":"initial","info_en":"Before restarting after the break, you plan the afternoon: steps 7-12, then the records. The work package was printed this morning.","info_ar":"قبل الاستئناف بعد الاستراحة تخطط لفترة ما بعد الظهر: الخطوات 7-12 ثم السجلات. طُبعت حزمة العمل هذا الصباح.","question_en":"What do you do first?","question_ar":"ما أول ما تفعله؟","options":[{"en":"Check that the printed procedure is still the current revision before continuing.","ar":"أتحقق من أن الإجراء المطبوع ما زال المراجعة السارية قبل المتابعة.","eff":3,"note_en":"A quick check that keeps the whole afternoon valid.","note_ar":"فحص سريع يُبقي فترة ما بعد الظهر كلها صحيحة."},{"en":"Carry on: it was printed this morning.","ar":"أتابع: لقد طُبع هذا الصباح.","eff":1,"note_en":"Usually fine, but nobody checked.","note_ar":"غالباً لا بأس، لكن أحداً لم يتحقق."},{"en":"Skip to the records to finish early.","ar":"أنتقل إلى السجلات لأنتهي مبكراً.","eff":0,"note_en":"Records before the work is done are false records.","note_ar":"السجلات قبل إنجاز العمل سجلات غير صحيحة."}],"cues":[{"en":"The work package was printed this morning.","ar":"طُبعت حزمة العمل هذا الصباح.","relevant":true},{"en":"Six of twelve steps are complete.","ar":"أُنجزت ست خطوات من اثنتي عشرة.","relevant":true},{"en":"The workshop radio is broken.","ar":"مذياع الورشة معطل.","relevant":false},{"en":"Two transmitters are a newer model.","ar":"مرسلان من طراز أحدث.","relevant":false}],"debrief_en":"A controlled procedure is only as good as its revision status.","debrief_ar":"قيمة الإجراء المضبوط مرهونة بحالة مراجعته."},{"id":"revd","kind":"change","info_en":"Document control shows revision D was issued at 11:00, after you printed C. You do not yet know what changed.","info_ar":"يُظهر نظام ضبط الوثائق أن المراجعة D صدرت الساعة 11:00 بعد أن طبعت C. ولا تعرف بعد ما الذي تغيّر.","question_en":"What do you do now?","question_ar":"ماذا تفعل الآن؟","options":[{"en":"Continue on revision C and check later.","ar":"أتابع على المراجعة C وأتحقق لاحقاً.","eff":0,"note_en":"Working to a superseded procedure without knowing the change.","note_ar":"العمل وفق إجراء ملغى دون معرفة التغيير.","keep":true},{"en":"Pause at a safe point, get revision D, compare it with C for steps 1-12, and ask the procedure owner if completed steps are affected.","ar":"أتوقف عند نقطة آمنة، وأحصل على المراجعة D، وأقارنها بـ C للخطوات 1-12، وأسأل مالك الإجراء إن كانت الخطوات المنجزة متأثرة.","eff":3,"note_en":"Stops on uncertainty, finds the facts, and asks the owner about work already done.","note_ar":"يتوقف عند عدم اليقين ويجمع الحقائق ويسأل المالك عن العمل المنجز."},{"en":"Restart from step 1 on revision D without checking what changed.","ar":"أعيد البدء من الخطوة 1 على المراجعة D دون التحقق مما تغيّر.","eff":2,"note_en":"Safe but possibly wasteful; knowing the change first is better.","note_ar":"آمن لكنه قد يهدر الجهد؛ ومعرفة التغيير أولاً أفضل."},{"en":"Finish on C because you started on C.","ar":"أُكمل على C لأنني بدأت عليها.","eff":0,"note_en":"Starting on a revision is not permission to finish on it.","note_ar":"البدء على مراجعة لا يعني الإذن بالانتهاء عليها."}],"cues":[{"en":"Revision D was issued after you printed C.","ar":"صدرت المراجعة D بعد طباعة C.","relevant":true},{"en":"You do not know yet what changed.","ar":"لا تعرف بعد ما الذي تغيّر.","relevant":true},{"en":"Revision D was written by a different engineer.","ar":"كتب المراجعة D مهندس مختلف.","relevant":false},{"en":"The printer is low on toner.","ar":"حبر الطابعة منخفض.","relevant":false}],"debrief_en":"When the basis of the work changes and you do not know how, pause, find out, and ask the owner. Neither ignoring nor guessing is adaptive.","debrief_ar":"عندما يتغير أساس العمل ولا تعرف كيف، توقف واستعلم واسأل المالك. لا التجاهل ولا التخمين تكيّف."},{"id":"diff","kind":"change","info_en":"Revision D only corrects a typing error in the title of step 11. Steps 1-10 and 12 are unchanged; the procedure owner confirms completed steps stand.","info_ar":"تصحح المراجعة D خطأً مطبعياً في عنوان الخطوة 11 فقط. الخطوات 1-10 و12 لم تتغير، ويؤكد مالك الإجراء أن الخطوات المنجزة سارية.","question_en":"What do you do now?","question_ar":"ماذا تفعل الآن؟","options":[{"en":"Continue from step 7 on revision D, note the revision change in the record, and carry on.","ar":"أتابع من الخطوة 7 على المراجعة D، وأدوّن تغيير المراجعة في السجل، وأواصل.","eff":3,"note_en":"The change is minor and confirmed; the record shows exactly what happened.","note_ar":"التغيير بسيط ومؤكد؛ ويُظهر السجل ما حدث بالضبط.","keep":true},{"en":"Restart everything on revision D anyway.","ar":"أعيد كل شيء على المراجعة D على أي حال.","eff":1,"note_en":"Over-reaction: the owner confirmed the completed steps stand.","note_ar":"مبالغة: أكد المالك أن الخطوات المنجزة سارية."},{"en":"Go back to revision C since nothing important changed.","ar":"أعود إلى المراجعة C لأنه لم يتغير شيء مهم.","eff":0,"note_en":"You must work to the current revision even when the change is small.","note_ar":"يجب العمل وفق المراجعة السارية حتى إن كان التغيير صغيراً."},{"en":"Stop the job and wait for a meeting about the revision.","ar":"أوقف العمل وأنتظر اجتماعاً بشأن المراجعة.","eff":1,"note_en":"Nothing is left to resolve.","note_ar":"لم يبق ما يحتاج إلى حسم."}],"cues":[{"en":"Only the title of step 11 changed.","ar":"تغيّر عنوان الخطوة 11 فقط.","relevant":true},{"en":"The procedure owner confirmed completed steps stand.","ar":"أكد مالك الإجراء أن الخطوات المنجزة سارية.","relevant":true},{"en":"Revision D has a new cover page.","ar":"للمراجعة D صفحة غلاف جديدة.","relevant":false}],"debrief_en":"Once the facts are clear, the right response to a small change is a small adjustment, recorded honestly.","debrief_ar":"بعد اتضاح الحقائق، الاستجابة الصحيحة لتغيير صغير تعديل صغير يُسجَّل بأمانة."}]'::jsonb, '[{"label":"OECD Survey of Adult Skills (PIAAC), Cycle 2 database: adaptive problem solving","url":"https://www.oecd.org/en/data/datasets/PIAAC-2nd-Cycle-Database.html","as_of":"2026-10-10","benchmark_id":"OECD-PIAAC"},{"label":"CSO Ireland · PIAAC 2023 key findings (publishes the OECD averages)","url":"https://www.cso.ie/en/releasesandpublications/ep/p-piaac/programmefortheinternationalassessmentofadultcompetenciespiaac2023/keyfindings","as_of":"2026-10-10","benchmark_id":"OECD-PIAAC"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10","benchmark_id":"IAEA-1917"}]'::jsonb, 'published', 1, 5, 'p-training-mgr', '2026-09-28T09:00:00Z')
